args.command:
/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict'
const base = 'http://localhost:3149/product'
async function body(headers = {}) {
  const response = await fetch(base, { headers })
  assert.equal(response.status, 200)
  return response.text()
}
const shell = await body({ RSC: '1', 'Next-Router-Prefetch': '1', 'Next-Router-Segment-Prefetch': '/product/__PAGE__' })
const perLink = await body({ RSC: '1', 'Next-Router-Prefetch': '2' })
const direct = await body()
assert.match(shell, /Premium Widget/)
assert.match(shell, /Loading related products/)
for (const product of ['Compact Widget', 'Widget Carry Case']) {
  assert.ok("'!shell.includes(product), `${product} leaked into default prefetch`)
  assert.ok(perLink.includes(product), `${product} missing from per-link prefetch`)
  assert.ok(direct.includes(product), `${product} missing from direct navigation`)
}
console.log('"'Production prefetch stages and direct navigation verified.')
NODE"

